//! SigV4 test vectors generated by botocore (`tools/gen_sigv4_vectors.py`):
//! header signing (`S3SigV4Auth`), request URLs built by a real botocore S3
//! client, and pre-signed URLs (`generate_presigned_url`), all with fixed
//! credentials and a fixed clock.

use std::time::Duration;

use fsfast_http_transport::Url;
use fsfast_http_transport::header::{HeaderMap, HeaderName, HeaderValue};
use fsfast_s3::credentials::Credentials;
use fsfast_s3::endpoint::{Addressing, Endpoint};
use fsfast_s3::sigv4::{Signer, UNSIGNED_PAYLOAD, sha256_hex};
use serde_json::Value;

const AK: &str = "AKIDEXAMPLE";
const SK: &str = "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY";

fn vectors() -> Vec<Value> {
    let text = include_str!("data/sigv4_vectors.json");
    serde_json::from_str::<Value>(text).unwrap().as_array().unwrap().clone()
}

fn fixed_time() -> std::time::SystemTime {
    fsfast_s3::encode::parse_iso8601("2026-11-24T12:34:56Z").unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or_else(|| panic!("{k} missing in {v}"))
}

#[test]
fn header_signing_matches_botocore() {
    let mut n = 0;
    for v in vectors().iter().filter(|v| v["kind"] == "sign") {
        let name = s(v, "name");
        let url = Url::parse(s(v, "url")).unwrap();
        // The URL must survive parsing unchanged (it is what is sent).
        assert_eq!(url.as_str().trim_end_matches('/'), s(v, "url").trim_end_matches('/'), "{name}");
        let mut headers = HeaderMap::new();
        for h in v["headers"].as_array().unwrap() {
            let h = h.as_array().unwrap();
            headers.append(
                HeaderName::from_bytes(h[0].as_str().unwrap().to_ascii_lowercase().as_bytes())
                    .unwrap(),
                HeaderValue::from_str(h[1].as_str().unwrap()).unwrap(),
            );
        }
        let body = hex::decode(s(v, "body_hex")).unwrap();
        let payload = match s(v, "payload") {
            "unsigned" => UNSIGNED_PAYLOAD.to_owned(),
            _ => sha256_hex(&body),
        };
        assert_eq!(payload, s(v, "x_amz_content_sha256"), "{name}: payload hash");
        let token = v["token"].as_str().map(str::to_owned);
        let creds = Credentials::new(AK, SK, token, None);
        let out = Signer::new("s3")
            .sign(
                s(v, "method"),
                &url,
                &mut headers,
                &payload,
                &creds,
                s(v, "region"),
                fixed_time(),
            )
            .unwrap();
        assert_eq!(out.canonical_request, s(v, "canonical_request"), "{name}: canonical request");
        assert_eq!(out.string_to_sign, s(v, "string_to_sign"), "{name}: string to sign");
        assert_eq!(headers["authorization"], s(v, "authorization"), "{name}: authorization");
        assert_eq!(headers["x-amz-date"], s(v, "x_amz_date"), "{name}");
        n += 1;
    }
    assert!(n >= 25, "only {n} signing vectors");
}

fn endpoint_for(v: &Value) -> Endpoint {
    let mut e = match v["endpoint"].as_str() {
        Some(u) => Endpoint::custom(u).unwrap(),
        None => Endpoint::aws(),
    };
    e.addressing = Addressing::parse(s(v, "addressing")).unwrap();
    if s(v, "name") == "url-dualstack" {
        e.dualstack = true;
    }
    e
}

fn query_params(v: &Value) -> Vec<(String, String)> {
    // botocore's serialization of the operation parameters.
    let p = &v["params"];
    let mut q = Vec::new();
    match s(v, "op") {
        "list_objects_v2" => {
            q.push(("list-type".into(), "2".into()));
            for (k, wire) in [
                ("Prefix", "prefix"),
                ("Delimiter", "delimiter"),
                ("MaxKeys", "max-keys"),
                ("ContinuationToken", "continuation-token"),
                ("StartAfter", "start-after"),
            ] {
                match &p[k] {
                    Value::String(x) => q.push((wire.into(), x.clone())),
                    Value::Number(x) => q.push((wire.into(), x.to_string())),
                    _ => {}
                }
            }
            q.push(("encoding-type".into(), "url".into()));
        }
        "list_object_versions" => {
            q.push(("versions".into(), String::new()));
            for (k, wire) in [
                ("KeyMarker", "key-marker"),
                ("Prefix", "prefix"),
                ("VersionIdMarker", "version-id-marker"),
            ] {
                if let Value::String(x) = &p[k] {
                    q.push((wire.into(), x.clone()));
                }
            }
            q.push(("encoding-type".into(), "url".into()));
        }
        "upload_part" => {
            q.push(("partNumber".into(), p["PartNumber"].to_string()));
            q.push(("uploadId".into(), s(p, "UploadId").into()));
        }
        "get_object" => {
            if let Value::String(x) = &p["VersionId"] {
                q.push(("versionId".into(), x.clone()));
            }
        }
        _ => {}
    }
    q
}

fn sorted_pairs(pairs: impl IntoIterator<Item = (String, String)>) -> Vec<(String, String)> {
    let mut v: Vec<_> = pairs.into_iter().collect();
    v.sort();
    v
}

fn url_pairs(url: &Url) -> Vec<(String, String)> {
    sorted_pairs(url.query().unwrap_or("").split('&').filter(|p| !p.is_empty()).map(|p| {
        let (a, b) = p.split_once('=').unwrap_or((p, ""));
        (a.to_owned(), b.to_owned())
    }))
}

fn vector_pairs(v: &Value) -> Vec<(String, String)> {
    sorted_pairs(v["query"].as_array().unwrap().iter().map(|p| {
        let p = p.as_array().unwrap();
        (p[0].as_str().unwrap().to_owned(), p[1].as_str().unwrap().to_owned())
    }))
}

#[test]
fn request_urls_match_botocore() {
    let mut n = 0;
    for v in vectors().iter().filter(|v| v["kind"] == "url") {
        let name = s(v, "name");
        let e = endpoint_for(v);
        let url = e
            .url(Some(s(v, "bucket")), v["key"].as_str(), &query_params(v), s(v, "region"))
            .unwrap();
        assert_eq!(url.scheme(), s(v, "scheme"), "{name}");
        let netloc = match url.port() {
            Some(p) => format!("{}:{p}", url.host_str().unwrap()),
            None => url.host_str().unwrap().to_owned(),
        };
        assert_eq!(netloc, s(v, "netloc"), "{name}: host");
        assert_eq!(url.path(), s(v, "path"), "{name}: path");
        assert_eq!(url_pairs(&url), vector_pairs(v), "{name}: query");
        n += 1;
    }
    assert!(n >= 40, "only {n} URL vectors");
}

#[test]
fn presigned_urls_match_botocore() {
    let mut n = 0;
    for v in vectors().iter().filter(|v| v["kind"] == "presign") {
        let name = s(v, "name");
        let e = endpoint_for(v);
        let mut q = Vec::new();
        if let Some(ver) = v["version_id"].as_str() {
            q.push(("versionId".to_owned(), ver.to_owned()));
        }
        let ours = e.url(Some(s(v, "bucket")), Some(s(v, "key")), &q, s(v, "region")).unwrap();
        assert_eq!(ours.path(), s(v, "path"), "{name}: path");
        // botocore presigns AWS virtual-hosted URLs against the legacy global
        // host (`bucket.s3.amazonaws.com`) whatever the region; fsfast uses
        // the regional host (which also works in opt-in regions and for new
        // buckets). Sign the URL botocore used to compare the signatures.
        let url = Url::parse(&format!("{}://{}{}", s(v, "scheme"), s(v, "netloc"), ours.path()))
            .unwrap();
        let mut url = url;
        url.set_query(ours.query());
        let creds = Credentials::new(AK, SK, v["token"].as_str().map(str::to_owned), None);
        let signed = Signer::new("s3")
            .presign(
                "GET",
                &url,
                &creds,
                s(v, "region"),
                fixed_time(),
                Duration::from_secs(v["expires"].as_u64().unwrap()),
            )
            .unwrap();
        assert_eq!(signed.path(), s(v, "path"), "{name}: path");
        assert_eq!(url_pairs(&signed), vector_pairs(v), "{name}: query and signature");
        n += 1;
    }
    assert!(n >= 7, "only {n} presign vectors");
}
